const parse=v=>{if(typeof v==='string'){try{return JSON.parse(v);}catch{return v;}}return v;},num=v=>Number.isFinite(Number(v))?Number(v):0,pretty=v=>String(v??'').replaceAll('_',' ').replaceAll('@',' ').replaceAll('{','').replaceAll('}','').replace(/\s+/g,' ').trim(),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=v=>num(v).toLocaleString(undefined,{maximumFractionDigits:2,notation:Math.abs(num(v))>=1e6?'compact':'standard'});
