const knownStatue=v=>v==null||v===''||typeof v==='boolean'||!Number.isFinite(Number(v))||Number(v)<0?null:Number(v);
const statueNumber=v=>v==null?'Unknown':fmt(v);
function statueBoostStatus(data,account={}){
 const out={},set=(name,state,detail='')=>out[name]={state,detail};
 [...statueValueBoosts,...statueDropBoosts].forEach(x=>set(x[0],'unknown','Effect not calculated from this export'));
 const grades=parse(data.StuG??data.StatueG);
 if(Array.isArray(grades))for(const [name,tier] of [['Onyx statues',2],['Zenith statue tier',3]]){const count=grades.filter(v=>knownStatue(v)!=null&&Number(v)>=tier).length,complete=(root.REMAINING_CATALOG?.StatueInfo||[]).every((_,i)=>knownStatue(grades[i])!=null);set(name,count?'owned':complete?'missing':'unknown',`${count} recorded at this tier or higher; applies per statue`);}
 const chars=root.CharacterTalents?.model?.(data,account,root.TALENT_CATALOG)||[];
 if(chars.length){const active=chars.flatMap(c=>c.loadouts[c.active]||[]),complete=chars.every(c=>parse(data['SL_'+c.id])!=null);for(const [name,re] of [['Voidwalker statue talent',/voodoo statufication/i],['Statue Metallurgy',/statue metallurgy/i]]){const found=active.filter(x=>re.test(x.name));set(name,found.length?'owned':complete?'missing':'unknown',found.length?`Lv ${Math.max(...found.map(x=>x.level))} in a saved active preset; character conditions still apply`:'No level recorded in saved active presets');}}
 const spelunk=parse(data.Spelunk),hardhat=root.WORLD7_CATALOG?.SpelunkUpg?.findIndex(x=>x[0]==='Grey_Hardhat');
 if(hardhat>=0){const level=knownStatue(parse(spelunk?.[5])?.[hardhat]);if(level!=null)set('Grey Hardhat',level>0?'owned':'missing',`Lv ${fmt(level)}`);}
 const artifact=root.WORLD5_CATALOG?.ArtifactInfo?.findIndex(x=>/Onyx_Lantern/i.test(x[0]));
 if(artifact>=0){const level=knownStatue(parse(parse(data.Sailing)?.[3])?.[artifact]);if(level!=null)set('World 5 Sailing',level>0?'owned':'missing',`Artifact tier ${fmt(level)}`);}
 return out;
}
function statues(data,account={},c=root.REMAINING_CATALOG,characterId=null){
 const ids=Object.keys(data).filter(k=>/^StatueLevels_\d+$/.test(k)).map(k=>num(k.split('_')[1])).sort((a,b)=>a-b),id=ids.includes(Number(characterId))&&characterId!=null?Number(characterId):ids[0],levels=parse(data['StatueLevels_'+id]),grades=parse(data.StuG??data.StatueG)||[];
 const rows=(c.StatueInfo||[]).map((r,i)=>{const saved=characterId==='account'?ids.map(player=>parse(parse(data['StatueLevels_'+player])?.[i])).filter(v=>knownStatue(v?.[0])!=null).sort((a,b)=>num(b[0])-num(a[0])||num(b[1])-num(a[1]))[0]:parse(levels?.[i]),level=knownStatue(saved?.[0]),grade=knownStatue(grades[i]);return{id:i,name:pretty(r[0]),effect:pretty(r[1]),level,progress:knownStatue(saved?.[1]),grade,tier:grade==null?'Tier unknown':['Normal','Gold','Onyx','Zenith'][Math.min(3,grade)]||'Tier unknown',rate:num(r[3]),world:num(r[4])+1,bonus:level==null?null:level*num(r[3]),icon:`assets/EquipmentStatues${i+1}.png`,source:statueSources[i]||'Special source',method:crystalWorlds.has(i)?'Crystal mob':'Direct drop'};});
 return{available:Array.isArray(levels),characterId:id,characterName:account.charNames?.[id]||`Character ${(id??0)+1}`,characters:ids.map(id=>({id,name:account.charNames?.[id]||`Character ${id+1}`})),rows,boostStatus:statueBoostStatus(data,account)};
}
function statueFarmView(m,mode){const source=`<footer class="rw-source-credit">Reference: <a href="https://docs.google.com/spreadsheets/d/1IcxwlHKPcw57PJxOWmtCJTP2Iv6ubdRSEwzMjbH476U/edit?gid=510141304#gid=510141304" target="_blank" rel="noopener noreferrer">Antho &amp; Arkh’s spreadsheet</a></footer>`;const boost=(title,rows)=>`<section class="rw-boost-card"><h3>${title}</h3>${rows.map(x=>{const s=m.boostStatus[x[0]]||{state:'unknown',detail:''},label=s.state==='owned'?'Owned':s.state==='missing'?'Not owned':'Check in game';return`<div title="${esc(x[1])}">${x[2]?`<img src="${x[2]}" data-image-fallback="hide" alt="">`:'<i class="rw-palette-swatch"></i>'}<span class="rw-bonus-state ${s.state}">${label}</span><strong>${x[0]}</strong><small>${esc(s.detail||x[1])}</small></div>`;}).join('')}</section>`;const groups=statueGroups.map(g=>{const other=g.title==='Other Statues',rows=g.ids.map(id=>m.rows[id]).filter(Boolean);return`<section class="rw-world-card${other?' rw-world-other':''}"><header><strong>${g.title}</strong><span>${esc(g.method)}</span></header><div class="rw-world-rows">${rows.map(x=>{const meta=other?otherStatueMeta[x.id]:null;return`<div><img src="${x.icon}" data-image-fallback="hide" alt=""><span><b>${esc(x.name)}</b><small>${esc(x.effect)}</small>${other?`<em>${esc(meta?.[0]||'')} · ${esc(meta?.[1]||'')} · ${esc(x.source)}</em>`:''}</span></div>`;}).join('')}</div></section>`;}).join('');return`<div class="rw-worlds">${groups}</div><div class="rw-boosts">${boost('Increase Statue Value',statueValueBoosts)}${boost('Get More Statue Drops',statueDropBoosts)}</div>${source}`;}
function dungeons(data,c=root.REMAINING_CATALOG){const d=parse(data.DungUpg)||[],levels=d[0]||[],formula=(r,l)=>r[3]==='add'?num(r[1])*l:num(r[1])*l/(l+num(r[2])||1);const passives=[...(c.DungPassiveStats||[]),...(c.DungPassiveStats2||[])].map((r,id)=>({id,name:pretty(r[0]),level:num(levels[id]),bonus:formula(r,num(levels[id])),unit:r[4]==='%'?'%':'',icon:`assets/DungPassive${id}.png`}));const shop=(c.DungFlurboShop||[]).map((r,id)=>({id,name:pretty(r[3]),description:pretty(r[4]),cost:num(r[1]),owned:num(d[2]?.[id])>0,icon:`assets/${r[0]}.png`}));return{available:Array.isArray(d)&&d.length>0,passives,shop,rank:num(d[4]?.[0]),credits:num(d[4]?.[1]),flurbos:num(d[4]?.[2])};}
