function obolEffectiveStats(name,rerolls={}){
 const base=obolBaseItems[name]||{},stats={};
 for(const key of ['STR','AGI','WIS','LUK','Defence','Weapon_Power','UQ1val','UQ2val']){
  const value=num(base[key])+num(rerolls[key]);if(!value)continue;
  let label=key;
  if(/^UQ/.test(key)){label=base[key.replace('val','txt')]||rerolls[key.replace('val','txt')];if(typeof label!=='string'||!label)continue;}
  if(key==='Weapon_Power'){const type=String(base.UQ1txt||name).toLowerCase();label=/mining/.test(type)?'Mining_Power':/fishin/.test(type)?'Fishing_Power':/choppin/.test(type)?'Choppin_Power':/catch/.test(type)?'Catching_Power':/obolbronzeworship/i.test(name)?'Worship_Power':/obolbronzetrapping/i.test(name)?'Trapping_Power':key;}
  stats[label]=(stats[label]||0)+value;
 }
 return stats;
}
function obols(data,account={}){const ids=Object.keys(data).filter(k=>/^ObolEqO0_\d+$/.test(k)).map(k=>num(k.split('_')[1])).sort((a,b)=>a-b),boards=[{id:'family',name:'Family',items:parse(data.ObolEqO1)||[],map:parse(data.ObolEqMAPz1)||{}},...ids.map(id=>({id,name:account.charNames?.[id]||`Character ${id+1}`,items:parse(data['ObolEqO0_'+id])||[],map:parse(data['ObolEqMAP_'+id])||{}}))];boards.forEach(b=>{b.slots=b.items.map((name,id)=>({id,name,stats:obolEffectiveStats(name,parse(b.map?.[id]||b.map?.[String(id)])||{}),displayName:pretty(obolBaseItems[name]?.displayName||name),icon:name&&name!=='Blank'?`assets/${name}.png`:null})).filter(x=>x.name&&x.name!=='Blank');b.totals={};b.slots.forEach(x=>Object.entries(x.stats).forEach(([k,v])=>{if(typeof v!=='number'||/DisplayType/.test(k))return;const stat=/^UQ[12]val$/.test(k)?x.stats[k.replace('val','txt')]:k;if(!stat||typeof stat!=='string')return;b.totals[stat]=(b.totals[stat]||0)+v;}));});return{available:boards.some(x=>x.slots.length),boards,fragments:num(data.CYObolFragments),inventory:num(parse(data.ObolInvOwn)?.reduce?.((a,b)=>a+num(b),0))};}
function prayers(data,account={},c=root.REMAINING_CATALOG){const ids=Object.keys(data).filter(k=>/^Prayers_\d+$/.test(k)).map(k=>num(k.split('_')[1])).sort((a,b)=>a-b),equipped=new Map;ids.forEach(id=>(parse(data['Prayers_'+id])||[]).filter(x=>num(x)>=0).forEach(x=>{const n=num(x);if(!equipped.has(n))equipped.set(n,[]);equipped.get(n).push(account.charNames?.[id]||`Character ${id+1}`);}));const rows=(c.PrayerInfo||[]).map((r,id)=>({id,name:pretty(r[0]),positive:pretty(r[1]),negative:pretty(r[2]),basePositive:num(r[3]),baseNegative:num(r[4]),soul:r[5],equipped:equipped.get(id)||[],icon:`assets/Prayer${id}.png`}));return{available:ids.length>0,rows};}
function refinery(data,c=root.REMAINING_CATALOG){const r=parse(data.Refinery)||[];return{available:Array.isArray(r)&&r.length>3,slots:(c.RefineryInfo||[]).map((x,id)=>({id,name:`Salt ${id+1}`,rank:num(r[id+3]?.[1]),cycle:num(r[id+3]?.[0]),auto:num(r[id+3]?.[3]),stored:num(r[2]?.[id]),inputs:x.slice(0,6).map((item,i)=>({item,qty:num(x[6+i])})).filter(x=>x.item!=='Blank'&&x.qty>0),output:x[12],icon:`assets/Refinery${id+1}.png`}))};}
function printer(data,account={}){
 const p=parse(data.Print??data.Printer)||[],extra=parse(data.PrinterXtra)||[],characters=[];
 const pairs=(list,active=false)=>{const out=[];for(let i=0;i+1<list.length;i+=2)if(typeof list[i]==='string'&&list[i]!=='Blank'&&num(list[i+1])>0)out.push({item:list[i],name:root.ITEM_NAMES?.[list[i]]||'Unknown item',rate:num(list[i+1]),icon:`assets/${list[i]}.png`,active});return out;};
 for(let id=0;id<Math.ceil(Math.max(0,p.length-5)/14);id++){const block=p.slice(5+id*14,5+(id+1)*14);characters.push({id,name:account.charNames?.[id]||`Character ${id+1}`,slots:[...pairs(block.slice(0,10)),...pairs(extra.slice(id*10,(id+1)*10)),...pairs(block.slice(10,14),true)]});}
 return{available:p.length>5,characters,main:characters.flatMap(c=>c.slots.filter(s=>s.active)),extra:[]};
}
function hole(data,c=root.REMAINING_CATALOG){const h=parse(data.Holes)||[],levels=h[0]||[],villagerNames=['Explorer','Engineer','Conjuror','Measurer','Librarian','Elder'];const villagers=villagerNames.map((name,id)=>({id,name,level:num(levels[id]),exp:num(h[1]?.[id]),resource:num(h[2]?.[id])}));const buildings=(c.HolesBuildings||[]).map((r,id)=>({id,name:pretty(r[0]),description:pretty(r[5]),owned:num(h[7]?.[id])>0,level:num(h[7]?.[id])}));return{available:Array.isArray(h)&&h.length>0,villagers,buildings};}
function savedField(data,account,names){for(const source of [data,account,account?.data,account?.rawData,account?.account,account?.account?.data])for(const name of names)if(source?.[name]!=null)return parse(source[name]);return null;}
