function holeLate(data,kind,account={}){const h=savedField(data,account,['Holes'])||[],options=savedField(data,account,['OptionsListAccount','OptLacc'])||[],hasSave=Array.isArray(h)&&h.length>0,explorerLevel=num(h?.[0]?.[0]),unlocked=explorerLevel>=(kind==='holeCove'?18:17);if(kind==='holeCove'){const shapeNames=['Gooey Triangle','Gooey Square','Gooey Pentagon','Gooey Hexagon','Gooey Heptagon','Gooey Nonagon','Quartz Prismagon','Quartz Cubigon','Quartz Pointagon','Quartz Octagogon','Quartz Noragon','Quartz Brillagon'],shapeRows=shapeNames.map((name,id)=>({id,name,count:num(options[654+id]),icon:`assets/HoleGshape${id}.png`,description:`${name} collected from Crystal Glunko monsters.`})),upgrades=coveNames.map((name,id)=>{const level=num(options[630+id]),value=level*coveBase[id];return{id:12+id,name,level,value,count:level,icon:`assets/HoleGshape${id%12}.png`,description:coveDescriptions[id].replace('{',fmt(value)).replace('}',fmt(1+value/100)).replace('$',fmt(value))};});return{available:hasSave||options.length>0,unlocked,explorerLevel,shapes:[...shapeRows,...upgrades],shapeRows,upgrades,blueSelection:num(options[666]),purpleSelection:num(options[667])};}const depth=Math.max(0,num(options[602])-2);return{available:hasSave||options.length>0,unlocked,explorerLevel,depth,items:[{id:0,name:'Depth Casts',count:depth,icon:null,description:'Each depth cast lowers the resources needed to destroy other skilling caverns.'},{id:1,name:'Coin Synergy',count:depth,icon:null,description:`Fountain coin value: ${fmt(Math.pow(1.1,depth))}x from Trench depth.`},{id:2,name:'Trench Trickledown',count:depth,icon:null,description:`+${fmt(15*depth)}% All Skill Efficiency and +${fmt(10*depth)}% All Skill EXP from Trench depth.`}]};}
